#include <BLEDevice.h>
#include <BLEUtils.h>
#include <BLEBeacon.h>
#include <BLEAdvertising.h>

void setup() {

  Serial.begin(115200);

  BLEDevice::init("Auto Beacon");

  BLEBeacon beacon;

  beacon.setManufacturerId(0x4C00);

  beacon.setProximityUUID(
    BLEUUID("74278BDA-B644-4520-8F0C-720EAF059935")
  );

  beacon.setMajor(1);
  beacon.setMinor(1);

  beacon.setSignalPower(-59);

  BLEAdvertisementData data;

  data.setFlags(0x04);
  data.setManufacturerData(beacon.getData());

  BLEAdvertising *advertising =
    BLEDevice::getAdvertising();

  advertising->setAdvertisementData(data);

  advertising->start();

  Serial.println("BLE beacon advertising");
}

void loop() {
  delay(1000);
}
